#include "lain/render/renderer.h"

#include "rendershaders.h" // generated by lain_embed_shaders: the SPIR-V of shaders/

#include <lain/image/convert.h>
#include <lain/string/format.h>

#include <archimedes/archimedes.h>

#include <algorithm>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <utility>

namespace lain::render
{
	// The shaders' blocks, std140 for the uniforms and std430 for the lights. Each must match its
	// declaration in shaders/scene.vert and shaders/scene.frag exactly.
	struct FrameConstants
	{
		float clipFromWorld[16];
		float eye[4];
		float ambient[4];
		std::uint32_t lightCount;
		std::uint32_t padding[3];
	};
	static_assert(sizeof(FrameConstants) == 112, "the Frame block is 112 bytes under std140");

	struct ObjectConstants
	{
		float worldFromMesh[16];
		float normalFromMesh[16];
		std::uint32_t flags;
		std::uint32_t padding[3];
	};
	static_assert(sizeof(ObjectConstants) == 144, "the Object block is 144 bytes under std140");
	static constexpr std::uint32_t kHasNormals = 1u;

	struct MaterialConstants
	{
		float diffuse[4];
		float specular[4];
	};

	struct LightConstants
	{
		float position[4];
		float direction[4];
		float radiance[4];
		float cone[4];
	};
	static_assert(sizeof(LightConstants) == 64, "a Light is 64 bytes under std430");

	struct Vertex
	{
		float position[3];
		float normal[3];
		float uv[2];
	};

	// A float target, so the picture read back is the light the shader computed, unquantised.
	static constexpr acm::Format kColourFormat = acm::Format::R32G32B32A32_Sfloat;

	static void copyMatrix(const math::Mat4d& m, float (&out)[16])
	{
		for (math::length_t c = 0; c < 4; ++c)
		{
			for (math::length_t r = 0; r < 4; ++r)
				out[4 * c + r] = float(m[c][r]);
		}
	}

	struct Renderer::Impl
	{
		acm::Device* device = nullptr;
		std::vector<std::string> problems;
		acm::DescriptorSetLayout layout;
		acm::Pipeline pipeline;
		acm::Sampler sampler;
	};

	struct GpuScene::Impl
	{
		const void* owner = nullptr; // the Renderer::Impl that uploaded it

		struct Mesh
		{
			acm::Buffer vertices;
			acm::Buffer indices;
		};
		std::vector<Mesh> meshes;
		std::vector<acm::Texture> textures; // the scene's, in its order
		acm::Texture white;					// what a material without a texture samples
		acm::Buffer frame;					// FrameConstants, rewritten for each view
		acm::Buffer objects;				// an ObjectConstants per instance, `objectStride` apart
		acm::Buffer lights;
		std::vector<acm::Buffer> materials;
		std::vector<acm::DescriptorSet> sets; // one per material, after the buffers they name

		// One draw per part of each instance, in the scene's order.
		struct Draw
		{
			std::size_t mesh;
			std::size_t set;
			std::uint32_t objectOffset;
			std::uint32_t firstIndex;
			std::uint32_t indexCount;
		};
		std::vector<Draw> draws;

		image::ColorRGBf ambient;
		image::ColorRGBf background;
		std::uint32_t lightCount = 0;
	};

	GpuScene::GpuScene(std::unique_ptr<Impl> impl)
		: m(std::move(impl))
	{
	}
	GpuScene::GpuScene(GpuScene&&) noexcept = default;
	GpuScene& GpuScene::operator=(GpuScene&&) noexcept = default;
	GpuScene::~GpuScene() = default;

	Renderer::Renderer(acm::Device& device)
		: m(std::make_unique<Impl>())
	{
		m->device = &device;
		if (!device.valid())
		{
			m->problems.push_back("the device is not usable");
			return;
		}

		m->layout = device.createDescriptorSetLayout({
			{0, acm::DescriptorType::UniformBuffer, acm::ShaderStage::Vertex | acm::ShaderStage::Fragment},
			{1, acm::DescriptorType::UniformBufferDynamic, acm::ShaderStage::Vertex | acm::ShaderStage::Fragment},
			{2, acm::DescriptorType::UniformBuffer, acm::ShaderStage::Fragment},
			{3, acm::DescriptorType::CombinedImageSampler, acm::ShaderStage::Fragment},
			{4, acm::DescriptorType::StorageBuffer, acm::ShaderStage::Fragment},
		});

		// A pipeline is built against a target's formats, not its size, so a 1 x 1 one stands for
		// every view's.
		acm::Texture probe = device.createTexture(kColourFormat, acm::Extent2D{1, 1});
		acm::RenderTarget target = device.createRenderTarget(probe, acm::RenderTargetConfig{acm::RenderTargetFinish::CopySrc, true});

		acm::PipelineShaders shaders;
		shaders.vertex = device.createShader(sceneVert());
		shaders.fragment = device.createShader(sceneFrag());
		acm::PipelineConfig config;
		config.vertexLayout = acm::VertexLayout{
			sizeof(Vertex),
			{
				{0, acm::Format::R32G32B32_Sfloat, offsetof(Vertex, position)},
				{1, acm::Format::R32G32B32_Sfloat, offsetof(Vertex, normal)},
				{2, acm::Format::R32G32_Sfloat, offsetof(Vertex, uv)},
			},
		};
		config.descriptorLayout = m->layout;
		config.depth = acm::DepthState::TestWrite(acm::CompareOp::Less);
		config.cullMode = acm::CullMode::None; // surfaces are seen from both sides
		m->pipeline = device.createPipeline(shaders, target, config);
		m->sampler = device.createSampler();

		if (!m->layout.valid() || !target.valid() || !m->pipeline.valid() || !m->sampler.valid())
		{
			const acm::Error error = !m->layout.valid()		? m->layout.error()
									 : !target.valid()		? target.error()
									 : !m->pipeline.valid() ? m->pipeline.error()
															: m->sampler.error();
			m->problems.push_back("the device refused the scene pipeline: " + error.message());
		}
	}

	Renderer::Renderer(Renderer&&) noexcept = default;
	Renderer& Renderer::operator=(Renderer&&) noexcept = default;
	Renderer::~Renderer() = default;

	const std::vector<std::string>& Renderer::problems() const
	{
		return m->problems;
	}

	// A texture as the device stores it: 8-bit sRGB, so the device decodes it to linear light before
	// it filters. A deeper or linear texture is narrowed by lain's own conversions first, once.
	static image::Image asSrgb8(const image::Image& texture)
	{
		if (texture.pixelFormat() == image::PixelFormat::RGBA8 && texture.colorSpace() == image::ColorSpace::sRGB)
			return texture;
		const image::Image wide = image::convert(texture, image::PixelFormat::RGBA32F);
		return image::convert(image::convert(wide, image::ColorSpace::sRGB), image::PixelFormat::RGBA8);
	}

	UploadResult Renderer::upload(const Scene& scene)
	{
		if (!m->problems.empty())
			return {std::nullopt, m->problems};
		std::vector<std::string> problems = validate(scene);
		if (!problems.empty())
			return {std::nullopt, std::move(problems)};

		acm::Device& device = *m->device;
		auto gpu = std::make_unique<GpuScene::Impl>();
		gpu->owner = m.get();
		gpu->ambient = scene.ambient;
		gpu->background = scene.background;
		gpu->lightCount = std::uint32_t(scene.lights.size());

		// Each result is checked once, where it is made, and the first refusal ends the upload.
		auto refused = [&](const std::string& what, const acm::Error& error)
		{
			problems.push_back(string::format("the device refused {}: {}", what, error.message()));
			return UploadResult{std::nullopt, std::move(problems)};
		};

		for (std::size_t i = 0; i < scene.meshes.size(); ++i)
		{
			const mesh::Mesh& mesh = *scene.meshes[i];
			std::vector<Vertex> vertices(mesh.positions.size());
			for (std::size_t v = 0; v < vertices.size(); ++v)
			{
				const math::Vec3f& p = mesh.positions[v];
				const math::Vec3f n = mesh.normals.empty() ? math::Vec3f{0.0f} : mesh.normals[v];
				const math::Vec2f t = mesh.uvs.empty() ? math::Vec2f{0.0f} : mesh.uvs[v];
				vertices[v] = Vertex{{p.x, p.y, p.z}, {n.x, n.y, n.z}, {t.x, t.y}};
			}
			GpuScene::Impl::Mesh uploaded;
			uploaded.vertices = device.createBuffer(vertices.size() * sizeof(Vertex), acm::BufferUsage::Vertex);
			uploaded.indices = device.createBuffer(mesh.indices.size() * sizeof(std::uint32_t), acm::BufferUsage::Index);
			if (!uploaded.vertices.valid())
				return refused(string::format("mesh {}'s vertices", i), uploaded.vertices.error());
			if (!uploaded.indices.valid())
				return refused(string::format("mesh {}'s indices", i), uploaded.indices.error());
			if (const acm::Error error = uploaded.vertices.write(vertices.data(), vertices.size() * sizeof(Vertex)))
				return refused(string::format("mesh {}'s vertices", i), error);
			if (const acm::Error error = uploaded.indices.write(mesh.indices.data(), mesh.indices.size() * sizeof(std::uint32_t)))
				return refused(string::format("mesh {}'s indices", i), error);
			gpu->meshes.push_back(std::move(uploaded));
		}

		for (std::size_t i = 0; i < scene.textures.size(); ++i)
		{
			const image::Image pixels = asSrgb8(*scene.textures[i]);
			if (!pixels.valid())
			{
				problems.push_back(string::format("texture {} could not be converted to 8-bit sRGB", i));
				return {std::nullopt, std::move(problems)};
			}
			acm::Texture texture = device.createTexture(acm::Format::R8G8B8A8_Srgb,
														acm::Extent2D{std::uint32_t(pixels.width()), std::uint32_t(pixels.height())},
														acm::TextureConfig{true, false});
			if (!texture.valid())
				return refused(string::format("texture {}", i), texture.error());
			if (const acm::Error error = texture.upload(pixels.data(), pixels.byteSize()))
				return refused(string::format("texture {}", i), error);
			gpu->textures.push_back(std::move(texture));
		}
		const std::uint8_t white[4] = {255, 255, 255, 255};
		gpu->white = device.createTexture(acm::Format::R8G8B8A8_Srgb, acm::Extent2D{1, 1});
		if (!gpu->white.valid())
			return refused("the white texture", gpu->white.error());
		if (const acm::Error error = gpu->white.upload(white, sizeof(white)))
			return refused("the white texture", error);

		gpu->frame = device.createBuffer(sizeof(FrameConstants), acm::BufferUsage::Uniform);
		if (!gpu->frame.valid())
			return refused("the frame constants", gpu->frame.error());

		// The instances' constants in one buffer, each at an offset the device can bind dynamically.
		const std::size_t alignment = std::max<std::size_t>(device.minUniformBufferOffsetAlignment(), 1);
		const std::size_t stride = (sizeof(ObjectConstants) + alignment - 1) / alignment * alignment;
		std::vector<std::uint8_t> objects(stride * std::max<std::size_t>(scene.instances.size(), 1));
		for (std::size_t i = 0; i < scene.instances.size(); ++i)
		{
			const Instance& instance = scene.instances[i];
			const mesh::Mesh& mesh = *scene.meshes[instance.mesh];
			ObjectConstants constants{};
			copyMatrix(instance.worldFromMesh, constants.worldFromMesh);
			const math::Mat3d linear{instance.worldFromMesh};
			const double det = math::determinant(linear);
			const math::Mat3d normal = std::abs(det) > 0 ? math::transpose(math::inverse(linear)) : math::Mat3d{1.0};
			copyMatrix(math::Mat4d{normal}, constants.normalFromMesh);
			constants.flags = mesh.normals.empty() ? 0u : kHasNormals;
			std::memcpy(objects.data() + i * stride, &constants, sizeof(constants));
			for (const mesh::Part& part : mesh.parts)
			{
				gpu->draws.push_back({instance.mesh, instance.materials[part.material], std::uint32_t(i * stride), part.firstIndex,
									  part.indexCount});
			}
		}
		gpu->objects = device.createBuffer(objects.size(), acm::BufferUsage::Uniform);
		if (!gpu->objects.valid())
			return refused("the instances' constants", gpu->objects.error());
		if (const acm::Error error = gpu->objects.write(objects.data(), objects.size()))
			return refused("the instances' constants", error);

		std::vector<LightConstants> lights(std::max<std::size_t>(scene.lights.size(), 1), LightConstants{});
		for (std::size_t i = 0; i < scene.lights.size(); ++i)
		{
			const Light& light = scene.lights[i];
			const math::Vec3d axis = light.kind == LightKind::Spot ? math::normalize(light.direction) : math::Vec3d{0.0, 0.0, 1.0};
			const double radians = 3.14159265358979323846 / 180;
			lights[i] = LightConstants{
				{float(light.position.x), float(light.position.y), float(light.position.z), light.kind == LightKind::Spot ? 1.0f : 0.0f},
				{float(axis.x), float(axis.y), float(axis.z), 0.0f},
				{float(light.colour.r * light.intensity), float(light.colour.g * light.intensity), float(light.colour.b * light.intensity),
				 0.0f},
				{float(std::cos(light.innerConeDegrees * radians)), float(std::cos(light.outerConeDegrees * radians)), 0.0f, 0.0f},
			};
		}
		gpu->lights = device.createBuffer(lights.size() * sizeof(LightConstants), acm::BufferUsage::Storage);
		if (!gpu->lights.valid())
			return refused("the lights", gpu->lights.error());
		if (const acm::Error error = gpu->lights.write(lights.data(), lights.size() * sizeof(LightConstants)))
			return refused("the lights", error);

		for (std::size_t i = 0; i < scene.materials.size(); ++i)
		{
			const Material& material = scene.materials[i];
			const MaterialConstants constants{
				{material.diffuse.r, material.diffuse.g, material.diffuse.b, 1.0f},
				{material.specular.r, material.specular.g, material.specular.b, material.shininess},
			};
			acm::Buffer buffer = device.createBuffer(sizeof(constants), acm::BufferUsage::Uniform);
			if (!buffer.valid())
				return refused(string::format("material {}", i), buffer.error());
			if (const acm::Error error = buffer.write(&constants, sizeof(constants)))
				return refused(string::format("material {}", i), error);
			acm::DescriptorSet set = device.createDescriptorSet(m->layout);
			if (!set.valid())
				return refused(string::format("material {}'s descriptors", i), set.error());
			set.setBuffer(0, gpu->frame);
			set.setDynamicBuffer(1, gpu->objects, sizeof(ObjectConstants));
			set.setBuffer(2, buffer);
			set.setTexture(3, material.texture ? gpu->textures[*material.texture] : gpu->white, m->sampler);
			set.setBuffer(4, gpu->lights);
			gpu->materials.push_back(std::move(buffer));
			gpu->sets.push_back(std::move(set));
		}

		return {GpuScene{std::move(gpu)}, {}};
	}

	RenderResult Renderer::render(GpuScene& scene, const View& view)
	{
		if (!m->problems.empty())
			return {{}, m->problems};
		std::vector<std::string> problems = validate(view);
		if (scene.m->owner != m.get())
			problems.push_back("the scene was uploaded by another renderer");
		if (!problems.empty())
			return {{}, std::move(problems)};

		acm::Device& device = *m->device;
		GpuScene::Impl& gpu = *scene.m;

		FrameConstants frame{};
		copyMatrix(clipFromCamera(view) * view.worldFromCamera.inverse().matrix(), frame.clipFromWorld);
		const math::Vec3d& eye = view.worldFromCamera.translation();
		frame.eye[0] = float(eye.x);
		frame.eye[1] = float(eye.y);
		frame.eye[2] = float(eye.z);
		frame.eye[3] = 1.0f;
		frame.ambient[0] = gpu.ambient.r;
		frame.ambient[1] = gpu.ambient.g;
		frame.ambient[2] = gpu.ambient.b;
		frame.lightCount = gpu.lightCount;
		if (const acm::Error error = gpu.frame.write(&frame, sizeof(frame)))
			return {{}, {"the device refused the view's constants: " + error.message()}};

		const acm::Extent2D extent{view.image.width, view.image.height};
		acm::Texture colour = device.createTexture(kColourFormat, extent);
		acm::RenderTarget target = device.createRenderTarget(colour, acm::RenderTargetConfig{acm::RenderTargetFinish::CopySrc, true});
		const std::size_t bytes = std::size_t{extent.width} * extent.height * 4 * sizeof(float);
		acm::Buffer readback = device.createBuffer(bytes, acm::BufferUsage::TransferDst);
		if (!colour.valid() || !target.valid() || !readback.valid())
		{
			const acm::Error error = !colour.valid() ? colour.error() : !target.valid() ? target.error()
																						: readback.error();
			return {{}, {"the device refused the view's target: " + error.message()}};
		}

		acm::Error recording;
		const acm::Error submitted = device.submitSync(
			[&](acm::CommandBuffer& cmd)
			{
				// Alpha 0 where nothing is drawn, so coverage reads back.
				recording = cmd.beginRendering(target, gpu.background.r, gpu.background.g, gpu.background.b, 0.0f);
				if (recording)
					return;
				cmd.setViewportAndScissor(extent);
				recording = cmd.bindPipeline(m->pipeline);
				for (const GpuScene::Impl::Draw& draw : gpu.draws)
				{
					if (recording)
						break;
					cmd.bindDescriptorSet(m->pipeline, gpu.sets[draw.set], draw.objectOffset);
					cmd.bindVertexBuffer(gpu.meshes[draw.mesh].vertices);
					cmd.bindIndexBuffer(gpu.meshes[draw.mesh].indices);
					recording = cmd.drawIndexed(draw.indexCount, 1, draw.firstIndex, 0, 0);
				}
				cmd.endRendering();
				cmd.copyTextureToBuffer(colour, readback);
			});
		if (recording)
			return {{}, {"the device refused the drawing: " + recording.message()}};
		if (submitted)
			return {{}, {"the device failed the drawing: " + submitted.message()}};

		image::Image picture(int(extent.width), int(extent.height), image::PixelFormat::RGBA32F, image::ColorSpace::Linear,
							 image::AlphaMode::Straight);
		const void* mapped = readback.map();
		if (!mapped)
			return {{}, {"the picture could not be read back"}};
		std::memcpy(picture.data(), mapped, bytes);
		readback.unmap();
		return {std::move(picture), {}};
	}
} // namespace lain::render
